import { zipSync, strToU8 } from "fflate";

const DISCLAIMER =
  "This is a demo file generated by BookStore. It contains placeholder text only — " +
  "not the actual book content — since this project has no licensed book files.";

// Very rough word-wrap (assumes a roughly fixed character width, good enough for
// a plain placeholder page — not meant to match real typeset line breaks).
const wrapText = (text, maxChars = 90) => {
  const words = text.split(/\s+/);
  const lines = [];
  let current = "";
  for (const word of words) {
    const next = current ? `${current} ${word}` : word;
    if (next.length > maxChars) {
      if (current) lines.push(current);
      current = word;
    } else {
      current = next;
    }
  }
  if (current) lines.push(current);
  return lines;
};

const escapePdfText = (text) => text.replace(/([()\\])/g, "\\$1");

/**
 * Builds a minimal, valid single-page PDF (hand-rolled, no dependency) containing
 * placeholder text about the book — not the real book content.
 */
export const createPlaceholderPdf = ({ title, author, description }) => {
  const bodyLines = [
    ...wrapText(description ?? "", 90),
    "",
    ...wrapText(DISCLAIMER, 90),
  ];

  const ops = [];
  ops.push(`BT /F1 22 Tf 50 720 Td (${escapePdfText(title)}) Tj ET`);
  ops.push(`BT /F1 13 Tf 50 695 Td (by ${escapePdfText(author)}) Tj ET`);
  bodyLines.forEach((line, i) => {
    const y = 655 - i * 16;
    if (y < 40) return; // stay on one page
    ops.push(`BT /F1 11 Tf 50 ${y} Td (${escapePdfText(line)}) Tj ET`);
  });
  const streamContent = ops.join("\n");
  const streamBytes = new TextEncoder().encode(streamContent).length;

  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
    `<< /Length ${streamBytes} >>\nstream\n${streamContent}\nendstream`,
  ];

  let pdf = "%PDF-1.4\n";
  const offsets = [];
  objects.forEach((obj, idx) => {
    offsets.push(new TextEncoder().encode(pdf).length);
    pdf += `${idx + 1} 0 obj\n${obj}\nendobj\n`;
  });
  const xrefStart = new TextEncoder().encode(pdf).length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  offsets.forEach((offset) => {
    pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  });
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`;

  return new Blob([pdf], { type: "application/pdf" });
};

/**
 * Builds a minimal, valid EPUB (a zip archive with the required OPF/NCX/XHTML
 * structure) containing placeholder text about the book — not the real content.
 */
export const createPlaceholderEpub = ({ title, author, description }) => {
  const escapeXml = (text) =>
    text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

  const containerXml = `<?xml version="1.0"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
  <rootfiles>
    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>
  </rootfiles>
</container>`;

  const contentOpf = `<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf" unique-identifier="BookId" version="2.0">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
    <dc:title>${escapeXml(title)}</dc:title>
    <dc:creator>${escapeXml(author)}</dc:creator>
    <dc:identifier id="BookId">urn:uuid:${crypto.randomUUID()}</dc:identifier>
    <dc:language>en</dc:language>
  </metadata>
  <manifest>
    <item id="chapter1" href="chapter1.xhtml" media-type="application/xhtml+xml"/>
    <item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/>
  </manifest>
  <spine toc="ncx">
    <itemref idref="chapter1"/>
  </spine>
</package>`;

  const tocNcx = `<?xml version="1.0" encoding="UTF-8"?>
<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1">
  <head></head>
  <docTitle><text>${escapeXml(title)}</text></docTitle>
  <navMap>
    <navPoint id="navpoint-1" playOrder="1">
      <navLabel><text>${escapeXml(title)}</text></navLabel>
      <content src="chapter1.xhtml"/>
    </navPoint>
  </navMap>
</ncx>`;

  const chapter1 = `<?xml version="1.0" encoding="UTF-8"?>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>${escapeXml(title)}</title></head>
<body>
  <h1>${escapeXml(title)}</h1>
  <h3>by ${escapeXml(author)}</h3>
  <p>${escapeXml(description ?? "")}</p>
  <p><em>${escapeXml(DISCLAIMER)}</em></p>
</body>
</html>`;

  const files = {
    mimetype: strToU8("application/epub+zip"),
    "META-INF/container.xml": strToU8(containerXml),
    "OEBPS/content.opf": strToU8(contentOpf),
    "OEBPS/toc.ncx": strToU8(tocNcx),
    "OEBPS/chapter1.xhtml": strToU8(chapter1),
  };

  const zipped = zipSync(files, { level: 0, mem: 0 });
  return new Blob([zipped], { type: "application/epub+zip" });
};
